SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(x ORDER BY schema_name,name) FROM(SELECT n.nspname schema_name,c.relname name,c.relkind::text kind,c.relpersistence::text persistence,c.relrowsecurity rls,c.relforcerowsecurity force_rls,pg_get_userbyid(c.relowner) owner,c.reloptions options FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_activity_v1' OR n.nspname='public' AND(c.relname='access_logs' OR c.relname LIKE 'audit_chain_%' OR c.relname LIKE 'access_logs_%'))x),
 'columns',(SELECT jsonb_agg(x ORDER BY schema_name,relation,position) FROM(SELECT n.nspname schema_name,c.relname relation,a.attnum position,a.attname name,format_type(a.atttypid,a.atttypmod) type,a.attnotnull not_null,a.attidentity::text identity,a.attgenerated::text generated,pg_get_expr(d.adbin,d.adrelid) default_expression,CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END collation FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped AND(c.relkind IN('r','v'))AND(n.nspname='ops_activity_v1' OR n.nspname='public' AND(c.relname='access_logs' OR c.relname LIKE 'audit_chain_%')))x),
 'constraints',(SELECT jsonb_agg(x ORDER BY schema_name,relation,name) FROM(SELECT n.nspname schema_name,c.relname relation,k.conname name,k.contype::text kind,k.condeferrable deferrable,k.condeferred initially_deferred,k.convalidated validated,pg_get_constraintdef(k.oid,true) definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_activity_v1' OR n.nspname='public' AND c.relname='access_logs')x),
 'indexes',(SELECT jsonb_agg(x ORDER BY schema_name,relation,name) FROM(SELECT n.nspname schema_name,c.relname relation,j.relname name,i.indisunique unique_index,i.indisprimary primary_index,i.indisvalid valid,i.indisready ready,pg_get_indexdef(i.indexrelid) definition,pg_get_expr(i.indpred,i.indrelid,true) predicate FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_class j ON j.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_activity_v1' OR n.nspname='public' AND c.relname='access_logs')x),
 'functions',(SELECT jsonb_agg(x ORDER BY name) FROM(SELECT p.oid::regprocedure::text name,l.lanname language,p.prosecdef security_definer,p.provolatile::text volatility,p.proconfig configuration,pg_get_userbyid(p.proowner) owner,pg_get_functiondef(p.oid) definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='ops_activity_v1')x),
 'triggers',(SELECT jsonb_agg(x ORDER BY relation,name) FROM(SELECT c.relname relation,t.tgname name,t.tgisinternal internal,t.tgenabled::text enabled,t.tgdeferrable deferrable,t.tginitdeferred initially_deferred,pg_get_triggerdef(t.oid,true) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(n.nspname='ops_activity_v1' OR n.nspname='public' AND c.relname='access_logs'))x),
 'views',(SELECT jsonb_agg(x ORDER BY name) FROM(SELECT c.relname name,c.reloptions options,pg_get_viewdef(c.oid,true) definition,CASE WHEN pg_relation_is_updatable(c.oid,false)&20=20 THEN 'YES' ELSE 'NO' END is_updatable,CASE WHEN pg_relation_is_updatable(c.oid,false)&8=8 THEN 'YES' ELSE 'NO' END is_insertable_into,CASE WHEN 'check_option=cascaded'=ANY(c.reloptions) THEN 'CASCADED' WHEN 'check_option=local'=ANY(c.reloptions) THEN 'LOCAL' ELSE 'NONE' END check_option FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_activity_v1' AND c.relkind='v')x),
 'sequences',(SELECT jsonb_agg(x ORDER BY name) FROM(SELECT c.relname name,format_type(s.seqtypid,NULL) type,s.seqstart start,s.seqincrement increment,s.seqmax maximum,s.seqmin minimum,s.seqcache cache,s.seqcycle cycle FROM pg_sequence s JOIN pg_class c ON c.oid=s.seqrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public')x)
);
